-- Schema source for NOVA 2.0. A timestamped migration must be generated by
-- `supabase migration new nova2_initial < supabase/schema.sql`.
-- Apply only to a separate synthetic staging project; never production.
create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text,
  language text not null default 'hi' check (language in ('hi','en')),
  theme text not null default 'midnight' check (theme in ('midnight','ivory')),
  legacy_nova1_id text unique,
  created_at timestamptz not null default now(),
  deleted_at timestamptz
);
create table public.chats (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null default 'New conversation',
  minister text not null default 'sakha' check (minister in ('sakha','diwan')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version bigint not null default 1,
  unique(id,user_id)
);
create table public.messages (
  id uuid primary key default gen_random_uuid(),
  chat_id uuid not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null check (role in ('user','assistant','system')),
  content text not null check (char_length(content) <= 20000),
  created_at timestamptz not null default now(),
  foreign key(chat_id,user_id) references public.chats(id,user_id) on delete cascade
);
create index messages_chat_created_idx on public.messages(chat_id,created_at);
create table public.files (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  kind text not null,
  mime text not null,
  size_bytes bigint not null check (size_bytes between 0 and 8000000),
  storage_key text not null,
  consent_at timestamptz not null,
  expires_at timestamptz not null,
  deleted_at timestamptz,
  created_at timestamptz not null default now()
);
create table public.wallets (
  user_id uuid primary key references auth.users(id) on delete cascade,
  balance_credits bigint not null default 0 check (balance_credits >= 0),
  updated_at timestamptz not null default now()
);
create table public.ledger_entries (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  delta_credits bigint not null check (delta_credits <> 0),
  reason text not null check (reason in ('topup','spend','refund','gift','adjustment')),
  ref_type text not null,
  ref_id text not null,
  created_at timestamptz not null default now(),
  unique(user_id,reason,ref_type,ref_id)
);
create table public.mock_payments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  mock_order_id text not null unique,
  amount_paise bigint not null check (amount_paise > 0),
  status text not null check (status in ('created','captured','failed','refunded')),
  event_ids text[] not null default '{}',
  created_at timestamptz not null default now()
);
create table public.usage_events (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete set null,
  feature text not null,
  model text not null,
  input_units bigint not null default 0,
  output_units bigint not null default 0,
  cost_paise bigint not null default 0 check (cost_paise >= 0),
  latency_ms integer not null default 0 check (latency_ms >= 0),
  ok boolean not null default false,
  created_at timestamptz not null default now()
);
create table public.diwan_jobs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  kind text not null check (kind in ('paper_reader','scam_check','rti','complaint','scheme_match')),
  status text not null default 'queued' check (status in ('queued','processing','complete','failed','expired')),
  input_ref text,
  output_json jsonb,
  pdf_key text,
  credits_charged integer not null default 0 check (credits_charged >= 0),
  created_at timestamptz not null default now(),
  expires_at timestamptz
);
create table public.schemes (
  id text primary key,
  name_en text not null,
  name_hi text not null,
  level text not null check (level in ('central','state')),
  state text,
  tags text[] not null default '{}',
  eligibility_json jsonb not null default '{}',
  benefits text not null,
  how_to_apply text[] not null default '{}',
  documents_required text[] not null default '{}',
  official_url text not null check (official_url like 'https://%'),
  last_verified date not null,
  status text not null check (status in ('active','closed','unknown'))
);
create table public.audit_log (
  id uuid primary key default gen_random_uuid(),
  actor text not null,
  action text not null,
  target text,
  meta jsonb not null default '{}',
  created_at timestamptz not null default now()
);
create table public.feature_flags (
  key text primary key,
  enabled boolean not null default false,
  rollout_pct integer not null default 0 check (rollout_pct between 0 and 100),
  updated_at timestamptz not null default now()
);

alter table public.profiles enable row level security;
alter table public.chats enable row level security;
alter table public.messages enable row level security;
alter table public.files enable row level security;
alter table public.wallets enable row level security;
alter table public.ledger_entries enable row level security;
alter table public.mock_payments enable row level security;
alter table public.usage_events enable row level security;
alter table public.diwan_jobs enable row level security;
alter table public.schemes enable row level security;
alter table public.audit_log enable row level security;
alter table public.feature_flags enable row level security;

create policy profiles_select_own on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy profiles_insert_own on public.profiles for insert to authenticated with check ((select auth.uid()) = id);
create policy profiles_update_own on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
create policy chats_owner_all on public.chats for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy messages_owner_all on public.messages for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy files_owner_select on public.files for select to authenticated using ((select auth.uid()) = user_id);
create policy wallet_owner_select on public.wallets for select to authenticated using ((select auth.uid()) = user_id);
create policy ledger_owner_select on public.ledger_entries for select to authenticated using ((select auth.uid()) = user_id);
create policy mock_payments_owner_select on public.mock_payments for select to authenticated using ((select auth.uid()) = user_id);
create policy usage_owner_select on public.usage_events for select to authenticated using ((select auth.uid()) = user_id);
create policy diwan_jobs_owner_select on public.diwan_jobs for select to authenticated using ((select auth.uid()) = user_id);
create policy schemes_public_read on public.schemes for select to anon,authenticated using (true);

grant select,insert,update on public.profiles to authenticated;
grant select,insert,update,delete on public.chats,public.messages to authenticated;
grant select on public.files,public.wallets,public.ledger_entries,public.mock_payments,public.usage_events,public.diwan_jobs to authenticated;
grant select on public.schemes to anon,authenticated;
